import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
  // Background: signed in as the Northwind member, with a draft vendor
  const member = await apiAs("member");
  const ownVendorRes = await member.post("/api/vendors", {
    data: { name: uniqueName("DOC07 Own Vendor"), category: "software", contact_email: "own-vendor@example.com" },
  });
  expect(ownVendorRes.status(), await ownVendorRes.text()).toBe(201);
  expect((await ownVendorRes.json()).status).toBe("draft");

  // Given a document exists in tenant "Globex Procurement"
  const globex = await apiAs("otherTenant");
  const globexVendorRes = await globex.post("/api/vendors", {
    data: { name: uniqueName("DOC07 Globex Vendor"), category: "services", contact_email: "globex-vendor@example.com" },
  });
  expect(globexVendorRes.status(), await globexVendorRes.text()).toBe(201);
  const globexVendor = await globexVendorRes.json();

  const uploadRes = await globex.post(`/api/vendors/${globexVendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();

  // Sanity: the owning tenant can see it
  const ownerView = await globex.get(`/api/documents/${document.id}`);
  expect(ownerView.status(), await ownerView.text()).toBe(200);

  // When I request that document by id
  const res = await member.get(`/api/documents/${document.id}`);

  // Then the response status is 404 and the error code is document_not_found
  const bodyText = await res.text();
  expect(res.status(), bodyText).toBe(404);
  expect(JSON.parse(bodyText).error.code, bodyText).toBe("document_not_found");
});
